<section class="page-header"><div><a class="back-link" href="<?= url('estimates') ?>"><i class="fa-solid fa-arrow-left"></i> Back to estimates</a><h1><?= e($estimate['estimate_number']) ?></h1><p><?= e($estimate['company_name']) ?> · <?= e($estimate['estimate_type']) ?></p></div><div class="page-actions"><a class="button button-secondary" target="_blank" href="<?= url('estimates/'.$estimate['id'].'/print') ?>"><i class="fa-solid fa-print"></i> Print</a><a class="button button-primary" href="<?= url('estimates/'.$estimate['id'].'/print?format=pdf') ?>"><i class="fa-solid fa-file-pdf"></i> Download PDF</a></div></section>
<div class="invoice-view-grid"><section class="panel invoice-document"><div class="invoice-doc-head"><div><span class="brand-mark">RM</span><div><strong>Rankers Mind</strong><small>Kolkata, West Bengal, India</small></div></div><div><span class="status-badge <?= status_class($estimate['status']) ?>"><?= e($estimate['status']) ?></span><h2><?= e($estimate['estimate_type']) ?></h2></div></div><div class="invoice-meta"><div><span>Prepared for</span><strong><?= e($estimate['company_name']) ?></strong><p><?= nl2br(e($estimate['billing_address']?:$estimate['city'].', '.$estimate['state'])) ?></p></div><dl><div><dt>Estimate no.</dt><dd><?= e($estimate['estimate_number']) ?></dd></div><div><dt>Date</dt><dd><?= e(date('d M Y',strtotime($estimate['estimate_date']))) ?></dd></div><div><dt>Valid until</dt><dd><?= $estimate['valid_until']?e(date('d M Y',strtotime($estimate['valid_until']))):'—' ?></dd></div><div><dt>Project</dt><dd><?= e($estimate['project_name']?:'General') ?></dd></div></dl></div><div class="table-scroll"><table class="data-table invoice-lines"><thead><tr><th>Description</th><th>Qty</th><th>Rate</th><th>Tax</th><th>Amount</th></tr></thead><tbody><?php foreach($items as $item):?><tr><td><strong><?= e($item['description']) ?></strong></td><td><?= e($item['quantity']) ?></td><td><?= money($item['rate']) ?></td><td><?= e($item['tax_percent']) ?>%</td><td><strong><?= money($item['amount']) ?></strong></td></tr><?php endforeach;?></tbody></table></div><div class="invoice-totals"><dl><div><dt>Subtotal</dt><dd><?= money($estimate['subtotal']) ?></dd></div><div><dt>Tax</dt><dd><?= money($estimate['tax_total']) ?></dd></div><div><dt>Discount</dt><dd><?= money($estimate['discount_total']) ?></dd></div><div class="summary-total"><dt>Total</dt><dd><?= money($estimate['grand_total']) ?></dd></div></dl></div><?php if($estimate['notes']):?><div class="invoice-note"><strong>Notes</strong><p><?= nl2br(e($estimate['notes'])) ?></p></div><?php endif;?></section><aside><section class="panel"><div class="panel-head"><div><h2>Estimate workflow</h2><p>Record the client decision</p></div></div><?php if(can('invoices.edit')&&$estimate['status']!=='Converted'):?><form class="mini-form" method="post" action="<?= url('estimates/'.$estimate['id'].'/status') ?>"><?= csrf_field() ?><label>Status<select name="status"><?php foreach(['Draft','Sent','Accepted','Rejected','Expired'] as $s):?><option <?= $estimate['status']===$s?'selected':'' ?>><?= e($s) ?></option><?php endforeach;?></select></label><button class="button button-secondary button-block">Update status</button></form><?php endif;?><?php if(can('invoices.create')&&in_array($estimate['status'],['Sent','Accepted'],true)):?><form class="mini-form" method="post" action="<?= url('estimates/'.$estimate['id'].'/convert') ?>" data-confirm="Convert this estimate to a draft invoice?"><?= csrf_field() ?><button class="button button-success button-block"><i class="fa-solid fa-file-invoice-dollar"></i> Convert to invoice</button></form><?php endif;?></section></aside></div>
